using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;

namespace Impostor.Server.LlmBots.Maps
{
    internal sealed class NavNode
    {
        public NavNode(int index, string id, string room, Vector2 position)
        {
            Index = index;
            Id = id;
            Room = room;
            Position = position;
        }

        public int Index { get; }

        public string Id { get; }

        public string Room { get; }

        public Vector2 Position { get; }

        public List<int> Edges { get; } = new();
    }

    /// <summary>
    ///     A coarse walkable graph: bots walk from waypoint to waypoint in straight lines.
    /// </summary>
    internal sealed class NavGraph
    {
        private readonly Dictionary<string, NavNode> _byId = new();

        public List<NavNode> Nodes { get; } = new();

        /// <summary>
        ///     Gets or sets the wall data of the ship. When present, routes are found on it instead of on the waypoints.
        /// </summary>
        public CollisionGrid? Collision { get; set; }

        public NavNode Add(string id, string room, Vector2 position)
        {
            var node = new NavNode(Nodes.Count, id, room, position);
            Nodes.Add(node);
            _byId[id] = node;
            return node;
        }

        public NavNode this[string id] => _byId[id];

        public bool TryGet(string id, out NavNode node) => _byId.TryGetValue(id, out node!);

        public void Link(string a, string b) => Link(this[a], this[b]);

        public void Link(NavNode a, NavNode b)
        {
            if (a == b || a.Edges.Contains(b.Index))
            {
                return;
            }

            a.Edges.Add(b.Index);
            b.Edges.Add(a.Index);
        }

        public NavNode Nearest(Vector2 position)
        {
            NavNode? best = null;
            var bestDistance = float.MaxValue;
            foreach (var node in Nodes)
            {
                var d = Vector2.DistanceSquared(node.Position, position);
                if (d < bestDistance)
                {
                    bestDistance = d;
                    best = node;
                }
            }

            return best!;
        }

        /// <summary>
        ///     Finds a walkable route. The result starts at <paramref name="from"/> and ends at <paramref name="to"/>.
        /// </summary>
        public List<Vector2> FindPath(Vector2 from, Vector2 to)
        {
            var walled = Collision?.FindPath(from, to);
            if (walled != null)
            {
                return walled;
            }

            var start = Nearest(from);
            var goal = Nearest(to);
            var route = new List<Vector2> { from };

            if (start != goal)
            {
                var nodes = AStar(start, goal);
                if (nodes != null)
                {
                    route.AddRange(nodes.Select(n => n.Position));
                }
            }
            else
            {
                route.Add(start.Position);
            }

            route.Add(to);
            return Simplify(route);
        }

        public double PathLength(Vector2 from, Vector2 to)
        {
            var path = FindPath(from, to);
            double total = 0;
            for (var i = 1; i < path.Count; i++)
            {
                total += Vector2.Distance(path[i - 1], path[i]);
            }

            return total;
        }

        /// <summary>
        ///     Checks that every node can reach every other node.
        /// </summary>
        public bool IsConnected()
        {
            if (Nodes.Count == 0)
            {
                return true;
            }

            var seen = new HashSet<int> { 0 };
            var queue = new Queue<int>();
            queue.Enqueue(0);
            while (queue.Count > 0)
            {
                var current = queue.Dequeue();
                foreach (var next in Nodes[current].Edges)
                {
                    if (seen.Add(next))
                    {
                        queue.Enqueue(next);
                    }
                }
            }

            return seen.Count == Nodes.Count;
        }

        /// <summary>
        ///     Connects separate islands by linking the closest pair of nodes between them.
        /// </summary>
        public void ConnectIslands()
        {
            while (true)
            {
                var seen = new HashSet<int> { 0 };
                var queue = new Queue<int>();
                queue.Enqueue(0);
                while (queue.Count > 0)
                {
                    var current = queue.Dequeue();
                    foreach (var next in Nodes[current].Edges)
                    {
                        if (seen.Add(next))
                        {
                            queue.Enqueue(next);
                        }
                    }
                }

                if (seen.Count == Nodes.Count)
                {
                    return;
                }

                NavNode? bestA = null;
                NavNode? bestB = null;
                var best = float.MaxValue;
                foreach (var a in Nodes.Where(n => seen.Contains(n.Index)))
                {
                    foreach (var b in Nodes.Where(n => !seen.Contains(n.Index)))
                    {
                        var d = Vector2.DistanceSquared(a.Position, b.Position);
                        if (d < best)
                        {
                            best = d;
                            bestA = a;
                            bestB = b;
                        }
                    }
                }

                Link(bestA!, bestB!);
            }
        }

        private static List<Vector2> Simplify(List<Vector2> route)
        {
            var result = new List<Vector2>();
            foreach (var p in route)
            {
                if (result.Count == 0 || Vector2.Distance(result[^1], p) > 0.05f)
                {
                    result.Add(p);
                }
            }

            return result;
        }

        private List<NavNode>? AStar(NavNode start, NavNode goal)
        {
            var open = new PriorityQueue<int, float>();
            var cameFrom = new Dictionary<int, int>();
            var cost = new Dictionary<int, float> { [start.Index] = 0 };
            open.Enqueue(start.Index, 0);

            while (open.Count > 0)
            {
                var current = open.Dequeue();
                if (current == goal.Index)
                {
                    var path = new List<NavNode> { Nodes[current] };
                    while (cameFrom.TryGetValue(current, out var previous))
                    {
                        current = previous;
                        path.Add(Nodes[current]);
                    }

                    path.Reverse();
                    return path;
                }

                foreach (var next in Nodes[current].Edges)
                {
                    var newCost = cost[current] + Vector2.Distance(Nodes[current].Position, Nodes[next].Position);
                    if (!cost.TryGetValue(next, out var known) || newCost < known)
                    {
                        cost[next] = newCost;
                        cameFrom[next] = current;
                        open.Enqueue(next, newCost + Vector2.Distance(Nodes[next].Position, goal.Position));
                    }
                }
            }

            return null;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;

namespace Impostor.Server.LlmBots.Maps
{
    /// <summary>
    ///     One place a bot has to stand for a while to do (a part of) a task.
    /// </summary>
    internal sealed record TaskStop(Vector2 Position, string Room, string Label, double Seconds);

    /// <summary>
    ///     Turns a task from the map data into the walk a crewmate has to make to finish it.
    /// </summary>
    internal static class TaskPlanner
    {
        private static readonly Dictionary<string, double> Seconds = new()
        {
            ["SwipeCard"] = 4,
            ["FixWiring"] = 4,
            ["ClearAsteroids"] = 14,
            ["AlignEngineOutput"] = 7,
            ["SubmitScan"] = 11,
            ["InspectSample"] = 8,
            ["FuelEngines"] = 5,
            ["StartReactor"] = 8,
            ["UploadData"] = 8,
            ["CalibrateDistributor"] = 7,
            ["ChartCourse"] = 6,
            ["CleanO2Filter"] = 6,
            ["UnlockManifolds"] = 7,
            ["StabilizeSteering"] = 4,
            ["PrimeShields"] = 4,
            ["DivertPower"] = 5,
            ["VentCleaning"] = 5,
            ["EmptyGarbage"] = 5,
            ["EmptyChute"] = 5,
        };

        private static readonly string[] DownloadRooms = { "Cafeteria", "Electrical", "Weapons", "Nav", "Comms", "Security", "MedBay" };

        private static readonly string[] PowerTargets = { "Weapons", "LifeSupp", "Nav", "Shields", "UpperEngine", "LowerEngine", "Security", "Comms" };

        public static string Name(string taskType) => BotMap.DisplayName(taskType);

        public static List<TaskStop> Plan(BotMap map, TaskSpec spec, Random rng)
        {
            var stops = new List<TaskStop>();
            var name = Name(spec.TaskType);

            TaskStop AtConsole(TaskConsole c, string label, double seconds) => new(c.Position, c.Room, label, seconds);

            TaskStop AtRoom(string room, string label, double seconds) => new(map.RoomHub(room), room, label, seconds);

            var seconds = Seconds.GetValueOrDefault(spec.TaskType, 6);

            switch (spec.TaskType)
            {
                case "FixWiring" when spec.Consoles.Count >= 3:
                {
                    var chosen = spec.Consoles.OrderBy(_ => rng.Next()).Take(3).ToList();
                    var ordered = new List<TaskConsole> { chosen[0] };
                    chosen.RemoveAt(0);
                    while (chosen.Count > 0)
                    {
                        var next = chosen.OrderBy(c => Vector2.DistanceSquared(c.Position, ordered[^1].Position)).First();
                        chosen.Remove(next);
                        ordered.Add(next);
                    }

                    stops.AddRange(ordered.Select(c => AtConsole(c, name, seconds)));
                    break;
                }

                case "UploadData":
                {
                    var rooms = DownloadRooms.Where(map.HasRoom).ToList();
                    if (rooms.Count > 0)
                    {
                        stops.Add(AtRoom(rooms[rng.Next(rooms.Count)], "Download Data", seconds));
                    }

                    stops.AddRange(spec.Consoles.Take(1).Select(c => AtConsole(c, "Upload Data", seconds)));
                    break;
                }

                case "DivertPower":
                {
                    stops.AddRange(spec.Consoles.Take(1).Select(c => AtConsole(c, "Divert Power (source)", seconds)));
                    var targets = PowerTargets.Where(map.HasRoom).ToList();
                    if (targets.Count > 0)
                    {
                        stops.Add(AtRoom(targets[rng.Next(targets.Count)], "Divert Power (accept)", seconds));
                    }

                    break;
                }

                case "FuelEngines" when spec.Consoles.Count == 0:
                {
                    var engines = new[] { "UpperEngine", "LowerEngine", "Engine" }.Where(map.HasRoom).ToList();
                    var storage = map.HasRoom("Storage") ? "Storage" : (map.Rooms.FirstOrDefault() ?? "Cafeteria");
                    foreach (var engine in engines.Take(2))
                    {
                        stops.Add(AtRoom(storage, "Fuel Engines (grab fuel)", seconds));
                        stops.Add(AtRoom(engine, "Fuel Engines (fill engine)", seconds));
                    }

                    if (stops.Count == 0)
                    {
                        stops.Add(AtRoom(storage, name, seconds));
                    }

                    break;
                }

                default:
                {
                    if (spec.Consoles.Count > 0)
                    {
                        // Several consoles of one task are alternatives, the game picks one of them.
                        var console = spec.Consoles[rng.Next(spec.Consoles.Count)];
                        stops.Add(AtConsole(console, name, seconds));
                    }
                    else
                    {
                        var rooms = PreferredRooms(map, spec.TaskType).ToList();
                        var room = rooms.Count > 0 ? rooms[rng.Next(rooms.Count)] : map.Rooms.OrderBy(_ => rng.Next()).First();
                        stops.Add(AtRoom(room, name, seconds));
                    }

                    break;
                }
            }

            if (stops.Count == 0)
            {
                stops.Add(new TaskStop(map.SpawnCenter, "Cafeteria", name, seconds));
            }

            return stops;
        }

        private static IEnumerable<string> PreferredRooms(BotMap map, string taskType)
        {
            var wanted = taskType switch
            {
                "ChartCourse" => new[] { "Nav", "Cockpit" },
                "EmptyGarbage" => new[] { "Cafeteria", "Storage", "LifeSupp", "Kitchen", "CargoBay" },
                "EmptyChute" => new[] { "LifeSupp", "Storage", "Cafeteria" },
                "WaterPlants" => new[] { "Greenhouse", "Storage" },
                "ReplaceWaterJug" => new[] { "Office", "BoilerRoom", "Laboratory" },
                "StartFans" => new[] { "Engine", "Electrical" },
                _ => Array.Empty<string>(),
            };

            return wanted.Where(map.HasRoom);
        }
    }
}

